using HomestayBooking.Desktop.Models;
using System.Text.Json;
namespace HomestayBooking.Desktop.View;
public partial class FrmCustomerManagement : Form
{
    private int _page=1; private int _totalPages=1;private int _customerId;
    public FrmCustomerManagement(){InitializeComponent();btnSearchCustomer.Click+=async(_,_)=>{_page=1;await SearchAsync();};btnCustPrev.Click+=async(_,_)=>{if(_page>1){_page--;await SearchAsync();}};btnCustNext.Click+=async(_,_)=>{if(_page<_totalPages){_page++;await SearchAsync();}};btnSaveCustomer.Click+=async(_,_)=>await SaveAsync();dgvCustomers.CurrentCellChanged+=async(_,_)=>await LoadCustomerAsync();}
    private async Task SearchAsync(){try{var data=await DesktopApi.GetAsync<JsonElement>($"customers?q={Uri.EscapeDataString(txtCustomerSearch.Text)}&page={_page}");_page=data.GetProperty("page").GetInt32();_totalPages=data.GetProperty("totalPages").GetInt32();dgvCustomers.DataSource=DesktopApi.ToTable(data.GetProperty("items").EnumerateArray());DesktopApi.ShowColumns(dgvCustomers,("fullName","Họ tên"),("phoneNumber","SĐT"),("email","Email"),("hasAccount","Có tài khoản"));lblCustPage.Text=$"Trang {_page} / {_totalPages}";btnCustPrev.Enabled=_page>1;btnCustNext.Enabled=_page<_totalPages;}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    // Khách chọn trước tải về sau không được đè khách đang chọn; không còn dòng thì xóa ô cũ để không lưu nhầm.
    private int _customerVersion;
    private async Task LoadCustomerAsync(){try{var version=++_customerVersion;if(dgvCustomers.CurrentRow is null){ClearCustomer();return;}var raw=dgvCustomers.CurrentRow.Cells["id"].Value;var customerId=raw is JsonElement id?id.GetInt32():Convert.ToInt32(raw);var data=await DesktopApi.GetAsync<JsonElement>($"customers/{customerId}");if(version!=_customerVersion)return;_customerId=customerId;var c=data.GetProperty("customer");txtCustFullName.Text=Get(c,"fullName");txtCustPhone.Text=Get(c,"phoneNumber");txtCustEmail.Text=Get(c,"email");txtCustCitizenId.Text=Get(c,"citizenId");txtCustStudentId.Text=Get(c,"studentId");txtCustNote.Text=Get(c,"note");var has=c.GetProperty("hasAccount").GetBoolean();txtCustFullName.ReadOnly=has;txtCustEmail.ReadOnly=has;lblAccountBadge.Text=has?"Khách đã có tài khoản Web (chỉ sửa được ghi chú)":"Khách vãng lai / đặt hộ (có thể sửa họ tên, email)";dgvCustomerBookings.DataSource=List(data,"bookings");dgvCustomerVouchers.DataSource=List(data,"usableVouchers");}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private static string Get(JsonElement data,string key)=>data.TryGetProperty(key,out var v)&&v.ValueKind!=JsonValueKind.Null?v.ToString():string.Empty;
    private static System.Data.DataTable List(JsonElement d,string prop)=>DesktopApi.ToTable(d.GetProperty(prop).EnumerateArray());
    private void ClearCustomer(){_customerId=0;txtCustFullName.Clear();txtCustPhone.Clear();txtCustEmail.Clear();txtCustCitizenId.Clear();txtCustStudentId.Clear();txtCustNote.Clear();lblAccountBadge.Text="";dgvCustomerBookings.DataSource=dgvCustomerVouchers.DataSource=null;}
    private async Task SaveAsync(){if(_customerId==0){MessageBox.Show(this,"Chọn một khách trong danh sách để lưu.");return;}try{await DesktopApi.PutAsync<object>($"customers/{_customerId}",new{note=txtCustNote.Text,fullName=txtCustFullName.ReadOnly?null:txtCustFullName.Text,email=txtCustEmail.ReadOnly?null:txtCustEmail.Text,phoneNumber=txtCustPhone.Text});MessageBox.Show("Đã lưu thông tin khách hàng.");}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
}

